import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
function check(input, expected) {
  assert.equal(slugify(input), expected, `slugify(${JSON.stringify(input)})`);
}
if (mode === 'canonical') {
  check('Crème Brûlée', 'creme-brulee');
  check('Łódź', 'lodz');
  let count = 0;
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (!/^\p{L}$/u.test(letter) || !/^\p{Script=Latin}$/u.test(letter)) continue;
    const decomposed = letter.normalize('NFD');
    if (!/^[A-Za-z]\p{M}+$/u.test(decomposed)) continue;
    const expected = decomposed[0].toLowerCase();
    check(letter, expected);
    check(`x ${letter} y`, `x-${expected}-y`);
    check(decomposed, expected);
    count++;
  }
  assert.ok(count > 400, 'exercise broad canonical Latin coverage');
} else if (mode === 'special') {
  const cases = [
    ['Øresund', 'oresund'], ['smørrebrød', 'smorrebrod'],
    ['Æsir æon', 'aesir-aeon'], ['Œuvre cœur', 'oeuvre-coeur'],
    ['Straße ẞ', 'strasse-ss'], ['ŁÓDŹ ł', 'lodz-l'],
    ['Đà Nẵng đ', 'da-nang-d'], ['Ħal ħ', 'hal-h'],
    ['Ŧ ŧ', 't-t'], ['ı I', 'i-i'], ['Ĳ ĳssel', 'ij-ijssel'],
    ['ſ', 's'], ['ﬀ ﬁ ﬂ ﬃ ﬄ ﬅ ﬆ', 'ff-fi-fl-ffi-ffl-st-st'],
    ['Ǽ ǽ Ǣ ǣ Ǿ ǿ', 'ae-ae-ae-ae-o-o'],
    ['Crème/東京/Łódź/Йога/Άλφα', 'creme-東京-lodz-йога-άλφα']
  ];
  for (const [input, expected] of cases) check(input, expected);
} else if (mode === 'combining') {
  for (const [input, expected] of [
    ['Cre\u0300me Bru\u0302le\u0301e', 'creme-brulee'],
    ['a\u0301b', 'ab'], ['a\u0301\u0327\u0304b', 'ab'],
    ['A\u0308 Z\u0307', 'a-z'], ['ø\u0301æ\u0304ß\u0308', 'oaess'],
    ['  e\u0301--o\u0308! ', 'e-o'],
    ['a\u1ab0b a\u1dc0b a\u20d0b a\ufe20b', 'ab-ab-ab-ab']
  ]) check(input, expected);
} else if (mode === 'regression') {
  const baseline = s => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '-').replace(/^-+|-+$/g, '');
  for (const input of [
    '', '---', 'Hello, World!', '  --Release 2.0--  ',
    'a_b/c.d\\e', ' A\tB\nC ', '123 ٤٥٦ １２３ ①²',
    'Привет мир', 'Й Ё Ї Ѓ Ќ Ў', 'Ά Έ Ή Ί Ό Ύ Ώ Ϊ Ϋ ᾈ ᾦ',
    'Καλημέρα κόσμε', '東京 日本語 カタカナ が パ', '한글 가 각',
    'العربية فارسی', 'שלום', 'हिन्दी বাংলা', 'ไทย', 'ქართული',
    'Հայերեն', '中文', 'ᎠᎡᎢ', '𐐀𐐁', '🙂 Hello 🌍 World!',
    'Йога/Άλφα/東京', 'ＡＢＣ ① Ⅳ', 'α\u0301β и\u0306я'
  ]) check(input, baseline(input));
  // Exercise every non-Latin Unicode letter individually. This also catches
  // indiscriminate decomposition of accented Greek, Cyrillic, or Hangul.
  for (let cp = 0; cp <= 0x10ffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (/^\p{L}$/u.test(letter) && !/^\p{Script=Latin}$/u.test(letter)) {
      check(letter, baseline(letter));
    }
  }
} else {
  throw new Error('Unknown acceptance mode');
}
console.log(`OK: ${mode}`);
